        "**Top-down stance: Constructive but cautious.** The tape is in a melt-up regime: S&P 500 closed at a fresh ATH of 7,259.22 (+0.81% on the day), Nasdaq at a record 25,326.13 (+1.03%), VIX at 17.45 (low). The breadth has widened — small caps participated alongside tech, which is healthier than a tech-only narrow tape. But forward 12-month P/E is 20.9x, the 90th+ percentile of the post-2010 distribution and well above the 10-year average of 18.9x. Earnings have to actually grow 17% in 2026 (bottom-up consensus) AND the Fed has to deliver the priced-in cuts AND geopolitical risk has to fade — for the multiple to be earned, not just paid. Two of three is fragile.",
        "",
        "Below we lay out the four macro value blocks driving every ticker decision in this issue, then translate them into book positioning.",
