        "**The leadership pattern says risk-on continues, but the lagging sectors (defensive, consumer, deeply cyclical retail) say the rotation is selective, not broad.** This is consistent with mid-cycle melt-up rather than late-cycle blow-off.",
        "",
        "## Synthesis · Three Conditions That Would Break the Regime",
