        "**条件 3（地缘政治再升级）。** 伊朗扩大霍尔木兹封锁或军事升级。油价回到 130+。权益倍数因风险溢价上升而下修。概率：中等；该风险并未随油价回落而消失。",
        "",
        "## 对本期组合的含义（2026-05-05 issue）",
