          "* **布林带** 大概率更靠近下轨；如果财报后区间收紧，5–10 个交易日内可能形成方向性突破。",
          "* **ATR** 历史 4–6% 日波动；财报后会议日预计 5%+。",
          "",
          "三条诚实观察：(1) PLTR 在 200 日均线下方——多头线索里最常被忽略的单一技术事实。(2) RSI 37 + MACD 负是近期偏空设置，财报可向任一方向解决。(3) **对清晰 beat-and-raise 的温和反应是最强信号——边际买家在为已经被定价的财报付费，边际卖家在收下这个礼物。**",
          "",
          "## 阶段 1B · 基本面",
          "",
          "最近报告期：**Q1 2026（2026-05-04 盘后发布）**。",
          "",
          "**质量。** Q1 2026 收入 16.3 亿，**YoY +85%**，公司有数据以来最快增速（2020 至今）。超出共识 15.4 亿。**美国商业收入 5.95 亿，YoY +133%。** 增速最高、利润率最高、扩张最快的细分。调整后 EPS 0.33 vs 预期 0.28。NDR 139%（2025 Q4）——企业软件领域中最高之一。**质量维度上 PLTR 接近顶尖。**",
          "",
          "**安全性。** 历史上账面净现金；债务安全无虞。**强**，与典型 SaaS 高速增长公司画像相反。",
          "",
          "**估值。整个空头逻辑都在这里。** 市盈率约 215 倍。147 美元、上调后的 FY2026 指引下，远期 P/S 仍约 49 倍。2026 年初 TTM P/S 超过 100x；2026-04-02 收盘 P/S 约 86x。2020–2021 年的同类高速增长样本（SNOW、DDOG、CRWD）峰值远期 P/S 60–80x，随后 24 个月即便收入继续增长，估值仍压缩 50–70%。",
          "",
          "**结论：质量顶尖。安全强。估值拉伸至——历史上要么需要多季度持续 beat-and-raise、要么需要多年估值压缩才能调和。** 三个支柱中两个优秀，第三个是结构性的，单一财报无论多好都无法解决。**Q1 财报本身就是所需量级的 beat-and-raise——但盘后温和反应告诉你市场知道：在这个倍数上，再好也不够。**",
          "",
          "## 阶段 1C · 新闻",
          "",
          "1. **2026-05-04 盘后 Q1 2026 财报。** 收入 16.3 亿（+85%）；EPS 0.33 vs 0.28；**FY2026 指引上调至 76.5 亿至 76.6 亿（原 71.8 亿至 72 亿），+71% 增长。** 美国商业指引上调至 +120%+。指引上调约 +4.6 亿（高端）。分子明显正向。",
          "2. **HSBC 2026-05-01 由 Buy 下调至 Hold，目标价削减 54 美元至 205。** 财报前的估值降级。空头线程中最可信的单一声音，因为它是基于估值的价格判断，而非基于业务的基本面判断。",
          "3. **「Look For Exit Point」分析师评论。** 强化估值纪律叙事。",
          "4. **宏观：** 美联储维持，预期再两次降息。利率走低机械上利好高倍数；但 PLTR 倍数远超同业，利率 beta 不对称——降息小利好、风险关闭大利空。",
          "5. **AI capex 顺风。** AIP 是公开市场最清晰的企业 AI 货币化故事；capex 周期（大型科技 Q1 2026 6500 亿）是结构性背风。",
          "",
          "结论：分子新闻优秀（Q1 财报、上调指引、AIP 长趋势）。分母新闻混合（HSBC、估值评论、利率中性）。**诚实观察：公司多年来最好的新闻收到的价格反应温和到微负——这是估值是绑定约束的最干净信号。**",
          "",
          "## 阶段 1D · 情绪",
          "",
          "混合（比 CRCL 的单边正向更健康）。两条相互竞争的叙事并存：「最佳增速的 AI 赢家」vs 「估值跑过头」。年内空头叙事在价格战上获胜，多头叙事在基本面战上获胜。**牛市背离形态（情绪上 + 价格修正）——但背离必须由价格补涨或基本面减速来解决，而 Q1 财报至少未来 90 天内排除了基本面减速。** 多头主题散户主导；估值纪律主题机构主导。3–6 个月视角下机构主题通常主导价格形成。",
          "",
