      "",
      "**Honest exit clause:** Take profit at 75% gain on premium — directional thesis converting. **Avoid bear call spreads or short-call structures** despite the bearish view: a sudden BTC move to $100k could spike MSTR 20%+ in a session, and unlimited-loss structures are not appropriate. Close puts on any sign of BTC < $70k breaking through (model-implosion scenario already in price)."
