      "",
      "**空方。** 沟通中的修订正是空头论据所预测的：当 mNAV 压缩使股权增发不再增厚、现金储备稀薄、股息义务升级时，公司只有一个自由度——卖 BTC。措辞为「战略」不改变机制：每次被迫卖出都验证螺旋。把 MSTR 当作永久 BTC 敞口持有的投资者，现在持有的是一个每年清算一定比例来支付固定义务的基金。这在结构上严格劣于直接持有 BTC。",
      "",
      "## 阶段 3 · Research Manager + 风险综合",
      "",
      "**建议：Underweight（自 Hold 上调）。** 多方反驳「被迫卖出仍小」并不改变轨迹。「never sell」一旦打破，下一次 mNAV 压缩事件（BTC −20% 情景）会迫使在更差价位卖更多，进一步压缩 mNAV，迫使继续卖出。空方的结构性论据现在进入执行阶段。",
      "",
      "**策略动作。** 持仓者在任何强势中激进减仓。新长头不开仓。希望 BTC beta 的投资者切换到 BITX（2x BTC ETF）或现货——既然股权封装已确认会卖 BTC 来满足优先股股息现金需求，封装在现在严格劣于直接 BTC。",
      "",
      "## 阶段 4 · Trader 方案",
