      "**摘要。** Saylor 在 Q1 2026 财报会上反转「never sell」立场，结构性改变了让 MSTR 成为独特 BTC 工具的资本配置哲学。Hold 论据曾警告：当 mNAV 压缩且股息义务上升时 BTC 卖出不可避免——公司现已公开确认这一点。该股权不再是杠杆化 BTC 永久多头；它是一个每年清算一部分来支付固定 carry 的杠杆 BTC 储备。这在结构上严格劣于直接持有 BTC。激进减仓；不开仓；以 BITX 或现货 BTC 替代 beta。",
      "",
