      "**This block has materially changed since the 5/5 brief.** Trump's pause of 'Project Freedom' (the US naval escort of commercial vessels through the Strait of Hormuz) on 5/6 was the first concrete US policy step toward Iran de-escalation since the war began on 2026-02-28. The market response: WTI -6.3% to $96.21, Brent -7.73% with intraday print below $100 (first time since April 22), USO -2.3% to $144.17 the prior session and likely lower today. The geopolitical premium that lifted oil from $80 to $126 is now actively unwinding. Even partial de-escalation removes most of that premium; equilibrium below $90 is plausible within 4 to 8 weeks.",
      "",
      "**Implication:** USO Underweight conviction strengthens to High; long re-entry zone moves DOWN to $95 to $105 conditional on confirmed truce signing (was $115 to $120). Tactical short via puts that was put on 5/6 is now likely 50%+ in profit; close at the 50-75% target trigger. Most importantly: **the geopolitical tail risk that we listed as one of three regime-breaking conditions is now de-risking, not escalating.** That removes a potential downside catalyst from the broader equity book.",
      "",
      "## Sector Rotation Read",
      "",
      "5/6 tape: tech leading (Nasdaq +2.02%), oil/energy weak (USO -2.3% etc), defensive lagging (BRKB underperforming as flows favored beta). The cohort leadership pattern continues to say melt-up regime, not late-cycle blow-off. PLTR's -6.75% break is name-specific — it is following the Snowflake 2020-2022 pattern (high-multiple software stock undergoing multi-quarter P/S compression even while revenue continues to grow), not a cohort-wide signal.",
      "",
      "## Synthesis · The three regime-breaking conditions, updated",
      "",
      "**Condition 1 (Fed-led).** No CPI signal yet; probability still low. UNCHANGED.",
      "",
      "**Condition 2 (Capex digestion).** Watch July hyperscaler prints; META capex hike from 5/6 didn't crack the cohort but the next print is the test. UNCHANGED.",
      "",
      "**Condition 3 (Geopolitical re-escalation).** **DE-RISKING.** Trump's Project Freedom pause is the first concrete de-escalation step. If Iran-US truce is signed in next 4 weeks, this condition is removed from the worry list entirely. If Iran rejects the framework, the condition snaps back active.",
      "",
      "**Net stance: still Constructive, but with one less major risk to worry about (the geopolitical one is materially de-risking) and one more confirmed concern (multiple compression on muted post-print reactions).** The book positioning is still right; the conviction on the USO short and the avoid-extended-multiples discipline both strengthen.",
      "",
      "## Implications for the Ticker Book (2026-05-07 issue)",
      "",
      "**Highest conviction long:** GOOGL (Buy) — fresh ATH; AI capex monetisation continuing.",
      "**Defensive ballast:** BRKB (Overweight) — cash optionality validated by MSTR cohort revaluation.",
      "**Tranched AI exposure:** ORCL (Overweight, breakout digesting), INTC (Overweight, +12.92% breakout day held), META (Overweight, +33% revenue answers capex tax), AAPL (Overweight, near 52w high).",
      "**Wait-for-catalyst names:** CRCL (Hold, Q1 print 2026-05-11 in 2 sessions).",
      "**Trim or short:** TSLA (Underweight, holding range at +40% over GF Value), USO (Underweight HIGH conviction, regime change in execution), SNDK (Hold-trim, 5/6 -3.86% relative-strength distribution signal), APP (Hold, post-print muted-reaction validates the binding signal).",
      "**RATING DOWNGRADE on 2026-05-07:** **PLTR Hold → Underweight** on -6.75% break of post-Q1 holding range. The Snowflake 2020-2022 historical analogue (high-multiple software stock undergoing multi-quarter P/S compression while revenue continues to grow) is now in execution mode.",
      "**Crypto direct (NEW additions on 5/7):** **IBIT (Buy)** — BlackRock spot BTC ETF, the cleanest BTC vehicle now that MSTR is Underweight; **ETHB (Overweight)** — BlackRock staked ETH ETF, spot ETH + ~3% staking yield distributions monthly, structurally novel and the cleaner ETF-wrapper alternative to BMNR's equity wrapper.",
      "**Crypto-adjacent equity wrappers:** MSTR (Underweight maintained from 5/5, BTC up doesn't reverse Saylor reversal), BMNR (Hold, ETH at $2,412 lifts NAV mechanically; the BMNR thesis is now relative-value vs ETHB, not absolute).",
      "**Watch list:** LULU (Hold, JPMorgan downgrade 5/6, conditional re-entry trigger 3+ sessions above $135).",
      "",
      "**Honest exit clause:** If APP follow-through next week reverses (post-AH gain gets sold), the muted-reaction pattern becomes structural and APP rating drifts toward Underweight. If Iran rejects the truce framework, USO Underweight reverses and the geopolitical premium snaps back. Re-read this brief on either signal."
