      "",
      "**策略动作。** 持仓者：维持（如已按 5/6 计划在财报前减仓则无需再减）。新进者：479 财报后价位不开仓。条件再入场：5%+ 多日跟随至 510+ 确认机构买盘恢复（1% NAV 起仓）；或回撤至 400-420 区间作价值折价入场（1.5% NAV 起仓）。止损 370。",
